/**
 * Normalise LaTeX markup in question text.
 *
 * The bank was generated by several pipelines and the delimiters disagree:
 *
 *   - stems use `$…$` / `$$…$$`
 *   - some options and explanations carry bare `\{ … \}` with no delimiters,
 *     which is rendered literally as `\{ 1, 2 \}` instead of {1, 2}
 *   - some options wrap a single expression in display math (`$$ … $$`), which
 *     makes the option a tall block inside a one-line answer button
 *   - a few strings use `\( … \)` / `\[ … \]` delimiters, which the renderer
 *     did not understand
 *
 * The same transformation is applied to the database rows and to the JSON seed
 * files, so `npm run db:reset` reproduces the cleaned data.
 *
 *   node scripts/normalize-math.mjs --write     # apply to DB + seeds
 *   node scripts/normalize-math.mjs             # dry run, prints counts
 */
import fs from 'node:fs';
import path from 'node:path';

const WRITE = process.argv.includes('--write');

for (const file of ['.env.local', '.env']) {
  const full = path.join(process.cwd(), file);
  if (!fs.existsSync(full)) continue;
  for (const line of fs.readFileSync(full, 'utf8').split('\n')) {
    const match = line.match(/^\s*([A-Z0-9_]+)\s*=\s*(.*)\s*$/i);
    if (!match || process.env[match[1]]) continue;
    process.env[match[1]] = match[2].replace(/^["']|["']$/g, '');
  }
}

/** Convert one string to the canonical delimiter scheme. */
export function normalizeText(value, { inline = false } = {}) {
  if (typeof value !== 'string' || value.length === 0) return value;

  let next = value;

  // `\( … \)` → `$ … $`, `\[ … \]` → `$$ … $$`
  next = next.replace(/\\\(([\s\S]+?)\\\)/g, (_m, expr) => `$${expr.trim()}$`);
  next = next.replace(/\\\[([\s\S]+?)\\\]/g, (_m, expr) => `$$${expr.trim()}$$`);

  // Bare LaTeX runs, e.g. `\{ 1, 2 \}` or `\emptyset`, outside any math span.
  next = next
    .split(/(\$\$[\s\S]+?\$\$|\$[^$\n]+?\$)/)
    .map((part) => {
      if (part.startsWith('$')) return part;
      let text = part;
      text = text.replace(/\\\{([^{}]*?)\\\}/g, (_m, inner) => `$\\{ ${inner.trim()} \\}$`);
      text = text.replace(/\\emptyset/g, '$\\emptyset$');
      return text;
    })
    .join('');

  if (inline) {
    // Options are single-line answer buttons: display math would become a tall
    // block, so demote it to inline math.
    next = next.replace(/\$\$([\s\S]+?)\$\$/g, (_m, expr) => `$${expr.trim()}$`);
  }

  // Collapse accidental duplicates introduced above, e.g. `$$x$$` → keep.
  return next.replace(/\${3,}/g, '$$');
}

const QUESTION_FIELDS = ['stem', 'stemZh', 'explanation', 'explanationZh'];
const OPTION_FIELDS = ['options', 'optionsZh'];

function normalizeQuestion(question) {
  const next = { ...question };
  let changed = false;
  for (const field of QUESTION_FIELDS) {
    if (typeof next[field] === 'string') {
      const value = normalizeText(next[field]);
      if (value !== next[field]) { next[field] = value; changed = true; }
    }
  }
  for (const field of OPTION_FIELDS) {
    if (Array.isArray(next[field])) {
      const values = next[field].map((item) => normalizeText(item, { inline: true }));
      if (values.some((item, index) => item !== next[field][index])) { next[field] = values; changed = true; }
    }
  }
  return { next, changed };
}

// ─────────────────────────── JSON seed files ───────────────────────────
const SEED_DIR = path.join('prisma', 'seeds');
const SEED_KEYS = { question: 'stem', options: 'options' };
let seedFilesChanged = 0;
let seedRecordsChanged = 0;

for (const file of fs.readdirSync(SEED_DIR).filter((name) => name.endsWith('.json'))) {
  const full = path.join(SEED_DIR, file);
  const raw = fs.readFileSync(full, 'utf8');
  let parsed;
  try {
    parsed = JSON.parse(raw);
  } catch {
    continue;
  }
  const records = Array.isArray(parsed) ? parsed : null;
  if (!records) continue;

  let touched = 0;
  for (const record of records) {
    if (!record || typeof record !== 'object') continue;
    for (const [key, value] of Object.entries(record)) {
      if (typeof value === 'string' && (key === 'question' || key === 'explanation' || key === 'stem')) {
        const next = normalizeText(value);
        if (next !== value) { record[key] = next; touched++; }
      } else if (Array.isArray(value) && value.every((item) => typeof item === 'string')) {
        const next = value.map((item) => normalizeText(item, { inline: true }));
        if (next.some((item, index) => item !== value[index])) { record[key] = next; touched++; }
      }
    }
  }
  if (touched > 0) {
    seedFilesChanged++;
    seedRecordsChanged += touched;
    if (WRITE) fs.writeFileSync(full, `${JSON.stringify(records, null, 2)}\n`);
  }
  void SEED_KEYS;
}

console.log(`[seed] files with changes: ${seedFilesChanged}, fields changed: ${seedRecordsChanged}`);

// ─────────────────────────── Database ───────────────────────────
const { PrismaClient } = await import('@prisma/client');
const { PrismaPg } = await import('@prisma/adapter-pg');
const prisma = new PrismaClient({
  adapter: new PrismaPg({ connectionString: process.env.DATABASE_URL }),
});

const questions = await prisma.question.findMany({
  select: {
    id: true,
    stem: true,
    stemZh: true,
    options: true,
    optionsZh: true,
    explanation: true,
    explanationZh: true,
  },
});

let dbChanged = 0;
for (const question of questions) {
  const { next, changed } = normalizeQuestion(question);
  if (!changed) continue;
  dbChanged++;
  if (WRITE) {
    await prisma.question.update({
      where: { id: question.id },
      data: {
        stem: next.stem,
        stemZh: next.stemZh,
        options: next.options,
        optionsZh: next.optionsZh,
        explanation: next.explanation,
        explanationZh: next.explanationZh,
      },
    });
  }
}

console.log(`[db] questions needing normalisation: ${dbChanged} of ${questions.length}`);
if (!WRITE) console.log('[dry run] re-run with --write to apply');

await prisma.$disconnect();
